<?php
require_once '../../config/auth.php';
requestMethod('POST');
$user=requireLogin();
$data=getRequestData(); $receiverId=(int)($data['receiver_id']??0); $listingId=($data['listing_id']??'')!==''?(int)$data['listing_id']:null; $source=($data['source']??($listingId?'listing':'roommate'))==='listing'?'listing':'roommate'; if($receiverId<=0) jsonError('receiver_id is required.'); if($receiverId===currentUserId()) jsonError('You cannot connect with yourself.');
try{ $db=getDB(); if($source==='roommate'){ $stmt=$db->prepare('SELECT id FROM roommate_profiles WHERE user_id=? AND is_published=1 AND profile_visible=1'); $stmt->execute([$receiverId]); if(!$stmt->fetch()) jsonError('This user does not have a visible roommate profile.',400); }
$stmt=$db->prepare('SELECT * FROM connection_requests WHERE (sender_id=? AND receiver_id=?) OR (sender_id=? AND receiver_id=?) LIMIT 1'); $stmt->execute([currentUserId(),$receiverId,$receiverId,currentUserId()]); $existing=$stmt->fetch(); if($existing){ if($existing['status']==='accepted') jsonResponse(['success'=>true,'message'=>'Already connected.','connection_id'=>(int)$existing['id'],'status'=>'accepted']); if($existing['status']==='pending'){ if((int)$existing['sender_id']===currentUserId()){ $db->prepare('DELETE FROM connection_requests WHERE id=?')->execute([(int)$existing['id']]); logActivity($db,currentUserId(),'cancel_connection_request','Canceled connection request to user #'.$receiverId); jsonResponse(['success'=>true,'message'=>'Request canceled.','request_id'=>(int)$existing['id'],'status'=>'canceled']); } jsonResponse(['success'=>true,'message'=>'This user already sent you a request.','request_id'=>(int)$existing['id'],'status'=>'incoming_pending']); } if($existing['status']==='declined'){ $db->prepare("UPDATE connection_requests SET sender_id=?, receiver_id=?, status='pending', source=?, listing_id=?, created_at=NOW() WHERE id=?")->execute([currentUserId(),$receiverId,$source,$listingId,(int)$existing['id']]); jsonResponse(['success'=>true,'request_id'=>(int)$existing['id'],'status'=>'pending']); } }
$stmt=$db->prepare("INSERT INTO connection_requests (sender_id,receiver_id,status,source,listing_id) VALUES (?,?,'pending',?,?)"); $stmt->execute([currentUserId(),$receiverId,$source,$listingId]); $id=(int)$db->lastInsertId(); sendNotification($db,$receiverId,'connection',($user['name']??'Someone').' sent you a connection request.',$id); logActivity($db,currentUserId(),'connection_request','Sent connection request to user #'.$receiverId); jsonResponse(['success'=>true,'request_id'=>$id,'status'=>'pending']); }catch(Throwable $e){ jsonError('Could not send request.',500); }
